const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let wrangler;
try { wrangler = require("wrangler"); } catch (e) { broken("cannot load wrangler: " + e.message); }
if (typeof wrangler.unstable_readConfig !== "function") broken("unstable_readConfig is not exported");
const dir = fs.mkdtempSync("/tmp/q-");
fs.writeFileSync(dir + "/index.js", "export default { fetch() { return new Response('ok'); } };\n");
const cfg = dir + "/wrangler.json";
fs.writeFileSync(cfg, JSON.stringify({ name: "demo", main: "index.js", compatibility_date: "2025-01-01", queues: { producers: [{ binding: "MY_QUEUE" }] } }));
let config;
try {
  config = wrangler.unstable_readConfig({ config: cfg }, { hideWarnings: true });
} catch (e) {
  const m = String(e && e.message);
  if (/should have a string "queue" field/.test(m)) symptom("a Queue producer binding without a queue name is rejected by config validation");
  broken("unexpected error reading config: " + m);
}
const p = config && config.queues && config.queues.producers;
if (!Array.isArray(p) || p.length !== 1 || p[0].binding !== "MY_QUEUE" || p[0].queue !== undefined) broken("unexpected producers: " + JSON.stringify(p));
console.log("OK: a Queue producer binding without a queue name is accepted");

